from collections import deque

def solve(grid):
    if not grid:
        return []
    H = len(grid)
    W = len(grid[0])

    # locate the topmost row that contains a 7 (the barrier)
    min_7_row = H
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 7:
                min_7_row = min(min_7_row, r)

    # if there is no barrier, just return a copy
    if min_7_row == H:
        return [row[:] for row in grid]

    visited = [[False] * W for _ in range(H)]
    out = [row[:] for row in grid]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 7:
                visited[r][c] = True
                continue
            if not visited[r][c]:
                # collect one connected component of non-7 cells
                comp = []
                q = deque()
                q.append((r, c))
                visited[r][c] = True
                while q:
                    cr, cc = q.popleft()
                    comp.append((cr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if not visited[nr][nc] and grid[nr][nc] != 7:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                # count how many 8s belong to this component
                n = sum(1 for (cr, cc) in comp if grid[cr][cc] == 8)

                # separate cells above and below the barrier
                above = []
                below = []
                for (cr, cc) in comp:
                    if cr < min_7_row:
                        above.append((cr, cc))
                    else:
                        below.append((cr, cc))

                # sort below: row by row from bottom to top,
                # within each row fill outward from the centre
                below_by_row = {}
                for (cr, cc) in below:
                    below_by_row.setdefault(cr, []).append(cc)

                below_sorted = []
                for row in sorted(below_by_row.keys(), reverse=True):
                    cols = below_by_row[row]
                    left = min(cols)
                    right = max(cols)
                    centre = (left + right) / 2.0
                    cols.sort(key=lambda c: (abs(c - centre), c))
                    for col in cols:
                        below_sorted.append((row, col))

                # sort above: simple bottom-up, left-to-right
                above.sort(key=lambda x: (-x[0], x[1]))

                # desired fill order for this component
                order = below_sorted + above

                # clear the component, then write back the 8s
                for (cr, cc) in comp:
                    out[cr][cc] = 0
                for i in range(n):
                    cr, cc = order[i]
                    out[cr][cc] = 8

    return out
